<?php require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/functions.php'; $user=require_login(); $clientId=(int)($_GET['client_id']??$_POST['client_id']??0); $message=null; if($_SERVER['REQUEST_METHOD']==='POST'){ $amount=(float)($_POST['amount']??49); $ref='NUM-'.strtoupper(bin2hex(random_bytes(4))); $stmt=db()->prepare('INSERT INTO payments (user_id, client_id, amount, currency, status, reference, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'); $stmt->execute([$user['id'],$clientId,$amount,'USD','paid',$ref,date('c')]); $message="Payment recorded with reference $ref."; } ?>
<!doctype html><html><head><title>Payment</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><div class="card"><h1>Collect Payment</h1><?php if($message): ?><div class="alert success"><?= e($message) ?></div><?php endif; ?><form method="post"><input type="hidden" name="client_id" value="<?= $clientId ?>"><label>Amount</label><input type="number" step="0.01" name="amount" value="49.00"><button>Mark as Paid</button></form></div></main></body></html>
